// Junta os resultados de todas as consultas (Prometheus + Loki) num só
// objeto e monta o relatório HTML com a marca do cliente (mesmo padrão
// visual do wrapper em templates/client-dashboard/wrapper.html.tpl).
function firstValue(nodeName) {
  try {
    const items = $(nodeName).all();
    const result = items[0].json.data.result;
    if (!result || !result.length) return null;
    return parseFloat(result[0].value[1]);
  } catch (e) {
    return null;
  }
}

const cfg = $('Configuração').first().json;

const uptime = firstValue('Uptime');
const totalRequests = firstValue('Requisições totais');
const totalErrors = firstValue('Erros 5xx totais');
const p95 = firstValue('Latência p95 média');
const errorLogLines = firstValue('Linhas de log de erro');

const fmtInt = (v) => (v === null || Number.isNaN(v)) ? '-' : Math.round(v).toLocaleString('pt-BR');
const fmtPct = (v) => (v === null || Number.isNaN(v)) ? '-' : v.toFixed(2).replace('.', ',') + '%';
const fmtMs = (v) => (v === null || Number.isNaN(v)) ? '-' : Math.round(v * 1000).toLocaleString('pt-BR') + ' ms';

const errorRate = (totalRequests && totalErrors !== null && totalRequests > 0)
  ? (totalErrors / totalRequests) * 100
  : 0;

const now = new Date();
const periodLabel = now.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

const accent = cfg.client_primary_color || '#0EA5E9';

const html = `
<div style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:640px;margin:0 auto;background:#0a0c11;color:#e8eaef;border-radius:12px;overflow:hidden;border:1px solid #232838;">
  <div style="padding:24px 32px;border-bottom:2px solid ${accent};display:flex;align-items:center;gap:12px;">
    <img src="${cfg.client_logo_url}" alt="${cfg.client_name}" style="height:32px;">
    <div>
      <div style="font-size:15px;font-weight:600;">${cfg.client_name}</div>
      <div style="font-size:11px;color:#838da3;">Relatorio mensal de observabilidade &mdash; ${periodLabel}</div>
    </div>
  </div>
  <div style="padding:24px 32px;display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#12151d;border:1px solid #1a1e2a;border-radius:10px;padding:16px;">
      <div style="font-size:11px;color:#838da3;text-transform:uppercase;letter-spacing:0.04em;">Uptime</div>
      <div style="font-size:22px;font-weight:700;margin-top:4px;">${fmtPct(uptime)}</div>
    </div>
    <div style="background:#12151d;border:1px solid #1a1e2a;border-radius:10px;padding:16px;">
      <div style="font-size:11px;color:#838da3;text-transform:uppercase;letter-spacing:0.04em;">Requisicoes no periodo</div>
      <div style="font-size:22px;font-weight:700;margin-top:4px;">${fmtInt(totalRequests)}</div>
    </div>
    <div style="background:#12151d;border:1px solid #1a1e2a;border-radius:10px;padding:16px;">
      <div style="font-size:11px;color:#838da3;text-transform:uppercase;letter-spacing:0.04em;">Taxa de erro (5xx)</div>
      <div style="font-size:22px;font-weight:700;margin-top:4px;">${fmtPct(errorRate)}</div>
    </div>
    <div style="background:#12151d;border:1px solid #1a1e2a;border-radius:10px;padding:16px;">
      <div style="font-size:11px;color:#838da3;text-transform:uppercase;letter-spacing:0.04em;">Latencia p95 media</div>
      <div style="font-size:22px;font-weight:700;margin-top:4px;">${fmtMs(p95)}</div>
    </div>
  </div>
  <div style="padding:0 32px 24px;font-size:13px;color:#838da3;">
    Linhas de log de erro no periodo: <strong style="color:#e8eaef;">${fmtInt(errorLogLines)}</strong>
  </div>
  <div style="padding:16px 32px;border-top:1px solid #232838;font-size:11px;color:#838da3;text-align:center;">
    Powered by Arcus Cloud Security
  </div>
</div>
`;

return [{
  json: {
    subject: `Relatorio mensal - ${cfg.client_name} - ${periodLabel}`,
    html,
    to: cfg.client_email_to,
  }
}];
